import type { Href } from 'expo-router';

/*
 * Routes of the ads marketplace screens (the same paths as the website). Typed routes are generated by Metro, so new
 * screens are addressed through these builders until the generated route list catches up.
 */
const href = (path: string): Href => path as Href;

export const adsRoutes = {
  home: href('/ads'),
  create: href('/ads/create'),
  manage: href('/ads/manage'),
  browse: href('/ads/marketplace/browse'),
  offer: (offerId: string): Href => href(`/ads/marketplace/offers/${encodeURIComponent(offerId)}`),
  bookOffer: (offerId: string): Href => href(`/ads/marketplace/offers/${encodeURIComponent(offerId)}/book`),
  editOffer: (offerId: string): Href => href(`/ads/marketplace/offers/${encodeURIComponent(offerId)}/edit`),
  createOffer: href('/ads/marketplace/create-offer'),
  myOffers: href('/ads/marketplace/my-offers'),
  myBookings: href('/ads/marketplace/my-bookings'),
  booking: (bookingId: string): Href => href(`/ads/marketplace/bookings/${encodeURIComponent(bookingId)}`),
  bookingPayment: (bookingId: string): Href => href(`/ads/marketplace/bookings/${encodeURIComponent(bookingId)}/payment`),
  bookingProof: (bookingId: string): Href => href(`/ads/marketplace/bookings/${encodeURIComponent(bookingId)}/proof`),
  bookingReview: (bookingId: string): Href => href(`/ads/marketplace/bookings/${encodeURIComponent(bookingId)}/review`),
  becomeHost: href('/ads/marketplace/become-host'),
  becomeBusinessHost: href('/ads/marketplace/become-host/business'),
  becomeInfluencerHost: href('/ads/marketplace/become-host/influencer'),
  hostDashboard: href('/ads/marketplace/host-dashboard'),
  verification: href('/ads/marketplace/verification'),
  wallet: href('/eWallet'),
  login: href('/(auth)/login'),
};
